def U(c, a, b):
    """Kleinste vorhandene Texteinheit (aus ruth_text.py), die Kapitel c, Verse a–b umfasst; sonst die Kapiteleinheit."""
    best = CHAPTER[c]
    span = None
    for p in (D / "text-units").glob(f"TU-RUT-{c:03d}-*.json"):
        m = re.fullmatch(r"TU-RUT-(\d{3})-(\d{3})-(\d{3})", p.stem)
        if not m:
            continue
        lo, hi = int(m.group(2)), int(m.group(3))
        if lo <= a and b <= hi and (span is None or hi - lo < span):
            best, span = p.stem, hi - lo
    return best


